 func TestDefaultRunInteractiveDispatch_ClearsLoadingCardBeforeReturn(t *testing.T) {
 	t.Parallel()
@@
 	if !strings.Contains(out.String(), "\x1b[1A\x1b[2K\r") {
 		t.Fatalf("expected loading card cleanup escape sequences, got %q", out.String())
 	}
 }
+
+func TestNewDispatchStatusStyles_UsesActivityPalette(t *testing.T) {
+	t.Parallel()
+
+	styles := newDispatchStatusStyles(statusStyles{colorEnabled: true})
+
+	if got := styles.title.Render("title"); got != "\x1b[1;37mtitle\x1b[0m" {
+		t.Fatalf("unexpected title style render: %q", got)
+	}
+	if got := styles.subtitle.Render("subtitle"); got != "\x1b[90msubtitle\x1b[0m" {
+		t.Fatalf("unexpected subtitle style render: %q", got)
+	}
+	if got := styles.spinner.Render("•"); got != "\x1b[90m•\x1b[0m" {
+		t.Fatalf("unexpected spinner style render: %q", got)
+	}
+}
+
+func TestDispatchMarkdownStyles_UsesActivityPalette(t *testing.T) {
+	t.Parallel()
+
+	styles := dispatchMarkdownStyles()
+
+	if got := derefString(styles.Document.Color); got != "7" {
+		t.Fatalf("document color = %q, want 7", got)
+	}
+	if got := derefString(styles.H1.Color); got != "7" {
+		t.Fatalf("h1 color = %q, want 7", got)
+	}
+	if styles.H1.BackgroundColor != nil {
+		t.Fatal("expected h1 background color to be cleared")
+	}
+	if got := derefString(styles.Link.Color); got != "8" {
+		t.Fatalf("link color = %q, want 8", got)
+	}
+	if got := derefString(styles.Code.BackgroundColor); got != "236" {
+		t.Fatalf("inline code background = %q, want 236", got)
+	}
+	if styles.CodeBlock.Chroma == nil {
+		t.Fatal("expected code block chroma theme to be configured")
+	}
+	if got := derefString(styles.CodeBlock.Chroma.Text.Color); got != "7" {
+		t.Fatalf("code block text color = %q, want 7", got)
+	}
+}
+
+func derefString(v *string) string {
+	if v == nil {
+		return ""
+	}
