package cli

import (
	"context"
	"io"
	"strings"
	"testing"

	tea "github.com/charmbracelet/bubbletea"
	dispatchpkg "github.com/entireio/cli/cmd/entire/cli/dispatch"
)

type fakeDispatchProgram struct {
	model tea.Model
}

//nolint:ireturn // dispatchProgram interface contract (mirrors tea.Program)
func (p fakeDispatchProgram) Run() (tea.Model, error) {
	model, ok := p.model.(dispatchStatusModel)
	if !ok {
		return p.model, nil
	}
	model.result = dispatchRenderResult{markdown: "# generated dispatch\n"}
	return model, nil
}

func TestDefaultRunInteractiveDispatch_DoesNotUseAltScreen(t *testing.T) {
	t.Parallel()

	oldProgramFactory := newDispatchProgram
	newDispatchProgram = func(model tea.Model, _ io.Writer, altScreen bool) dispatchProgram {
		if altScreen {
			t.Fatal("did not expect alt-screen for dispatch loading state")
		}
		return fakeDispatchProgram{model: model}
	}
	t.Cleanup(func() {
		newDispatchProgram = oldProgramFactory
	})

	markdown, err := defaultRunInteractiveDispatch(context.Background(), io.Discard, dispatchpkg.Options{
		Since: "7d",
	})
	if err != nil {
		t.Fatal(err)
	}
	if markdown != "# generated dispatch\n" {
		t.Fatalf("unexpected markdown: %q", markdown)
	}
}

func TestDispatchStatusModel_ViewRendersInlineCard(t *testing.T) {
	t.Parallel()

	model := newDispatchStatusModel(io.Discard, dispatchpkg.Options{
		Since: "7d",
	}, func(context.Context) (string, error) {
		return "", nil
	})
	model.width = 80
	model.height = 24

	view := model.View()
	if strings.HasPrefix(view, "\n") {
		t.Fatalf("expected inline view without leading blank lines: %q", view)
	}
	if strings.HasPrefix(view, " ") {
		t.Fatalf("expected inline view without leading padding: %q", view)
	}
	if got := strings.Count(view, "\n"); got >= 20 {
		t.Fatalf("expected compact inline card, got %d lines", got+1)
	}
}

func TestDefaultRunInteractiveDispatch_ClearsLoadingCardBeforeReturn(t *testing.T) {
	t.Parallel()

	oldProgramFactory := newDispatchProgram
	newDispatchProgram = func(model tea.Model, _ io.Writer, _ bool) dispatchProgram {
		return fakeDispatchProgram{model: model}
	}
	t.Cleanup(func() {
		newDispatchProgram = oldProgramFactory
	})

	var out strings.Builder
	markdown, err := defaultRunInteractiveDispatch(context.Background(), &out, dispatchpkg.Options{
		Since: "7d",
	})
	if err != nil {
		t.Fatal(err)
	}
	if markdown != "# generated dispatch\n" {
		t.Fatalf("unexpected markdown: %q", markdown)
	}
	if !strings.Contains(out.String(), "\x1b[1A\x1b[2K\r") {
		t.Fatalf("expected loading card cleanup escape sequences, got %q", out.String())
	}
}

package cli

import (
	"bytes"
	"runtime"
	"strings"
	"sync"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/go-git/go-git/v6/x/plugin"
	"github.com/spf13/cobra"
)

func TestVersionFlag_OutputMatchesVersionCmd(t *testing.T) {
	t.Parallel()

	// Run "entire --version"
	root := NewRootCmd()
	var flagOut bytes.Buffer
	root.SetOut(&flagOut)
	root.SetErr(&bytes.Buffer{})
	root.SetArgs([]string{"--version"})
	if err := root.Execute(); err != nil {
		t.Fatalf("entire --version failed: %v", err)
	}

	// Run "entire version"
	root2 := NewRootCmd()
	var cmdOut bytes.Buffer
	root2.SetOut(&cmdOut)
	root2.SetErr(&bytes.Buffer{})
	root2.SetArgs([]string{"version"})
	if err := root2.Execute(); err != nil {
		t.Fatalf("entire version failed: %v", err)
	}

	if flagOut.String() != cmdOut.String() {
		t.Errorf("output mismatch:\n--version: %q\nversion:   %q", flagOut.String(), cmdOut.String())
	}
}

func TestVersionFlag_ContainsExpectedInfo(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	var out bytes.Buffer
	root.SetOut(&out)
	root.SetErr(&bytes.Buffer{})
	root.SetArgs([]string{"--version"})
	if err := root.Execute(); err != nil {
		t.Fatalf("entire --version failed: %v", err)
	}

	output := out.String()

	checks := []struct {
		name     string
		contains string
	}{
		{"version number", versioninfo.Version},
		{"go version", runtime.Version()},
		{"os", runtime.GOOS},
		{"arch", runtime.GOARCH},
	}
	for _, c := range checks {
		if !strings.Contains(output, c.contains) {
			t.Errorf("--version output missing %s (%q):\n%s", c.name, c.contains, output)
		}
	}
}

func TestRegisterObjectSigner_RegistersPlugin(t *testing.T) {
	resetPluginEntry("object-signer")
	registerObjectSignerOnce = sync.Once{}
	t.Cleanup(func() {
		resetPluginEntry("object-signer")
		registerObjectSignerOnce = sync.Once{}
	})

	RegisterObjectSigner()

	if !plugin.Has(plugin.ObjectSigner()) {
		t.Fatal("expected object signer plugin to be registered")
	}
}

func TestPersistentPostRun_SkipsHiddenParent(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()

	// Find the leaf command: entire hooks git post-rewrite
	// This exercises the real command tree where "hooks" is Hidden but its descendants are not.
	leaf, _, err := root.Find([]string{"hooks", "git", "post-rewrite"})
	if err != nil {
		t.Fatalf("could not find hooks git post-rewrite command: %v", err)
	}

	if leaf.Hidden {
		t.Fatal("leaf command should not be hidden itself — the test validates parent-chain detection")
	}

	// Walk the parent chain (excluding root) and confirm at least one ancestor is hidden.
	foundHidden := false
	for c := leaf.Parent(); c != nil && c != root; c = c.Parent() {
		if c.Hidden {
			foundHidden = true
			break
		}
	}
	if !foundHidden {
		t.Fatal("expected at least one hidden ancestor between the leaf and root")
	}
}

func TestPersistentPostRun_ParentHiddenWalk(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name       string
		buildTree  func() *cobra.Command // returns the leaf command to test
		wantHidden bool
	}{
		{
			name: "leaf hidden",
			buildTree: func() *cobra.Command {
				root := &cobra.Command{Use: "root"}
				child := &cobra.Command{Use: "child", Hidden: true}
				root.AddCommand(child)
				return child
			},
			wantHidden: true,
		},
		{
			name: "parent hidden, leaf visible",
			buildTree: func() *cobra.Command {
				root := &cobra.Command{Use: "root"}
				parent := &cobra.Command{Use: "parent", Hidden: true}
				leaf := &cobra.Command{Use: "leaf"}
				root.AddCommand(parent)
				parent.AddCommand(leaf)
				return leaf
			},
			wantHidden: true,
		},
		{
			name: "grandparent hidden, leaf visible",
			buildTree: func() *cobra.Command {
				root := &cobra.Command{Use: "root"}
				gp := &cobra.Command{Use: "gp", Hidden: true}
				parent := &cobra.Command{Use: "parent"}
				leaf := &cobra.Command{Use: "leaf"}
				root.AddCommand(gp)
				gp.AddCommand(parent)
				parent.AddCommand(leaf)
				return leaf
			},
			wantHidden: true,
		},
		{
			name: "no hidden ancestor",
			buildTree: func() *cobra.Command {
				root := &cobra.Command{Use: "root"}
				parent := &cobra.Command{Use: "parent"}
				leaf := &cobra.Command{Use: "leaf"}
				root.AddCommand(parent)
				parent.AddCommand(leaf)
				return leaf
			},
			wantHidden: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			cmd := tt.buildTree()

			// Replicate the parent-walk logic from PersistentPostRun
			gotHidden := false
			for c := cmd; c != nil; c = c.Parent() {
				if c.Hidden {
					gotHidden = true
					break
				}
			}

			if gotHidden != tt.wantHidden {
				t.Errorf("isHidden = %v, want %v", gotHidden, tt.wantHidden)
			}
		})
	}
}

