package dispatch

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
)

const cloudTimeout = 30 * time.Second

type CloudConfig struct {
	BaseURL string
	Token   string
	HTTP    *http.Client
	Timeout time.Duration
}

type CloudClient struct {
	baseURL string
	token   string
	http    *http.Client
}

func NewCloudClient(cfg CloudConfig) *CloudClient {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = api.BaseURL()
	}

	timeout := cfg.Timeout
	if timeout == 0 {
		timeout = cloudTimeout
	}

	httpClient := cfg.HTTP
	if httpClient == nil {
		httpClient = &http.Client{Timeout: timeout}
	} else if httpClient.Timeout == 0 {
		httpClient.Timeout = timeout
	}

	return &CloudClient{
		baseURL: strings.TrimRight(baseURL, "/"),
		token:   cfg.Token,
		http:    httpClient,
	}
}

type CreateDispatchRequest struct {
	Repo     any    `json:"repo,omitempty"`
	Org      string `json:"org,omitempty"`
	Since    string `json:"since"`
	Until    string `json:"until"`
	Branches any    `json:"branches"`
	Generate bool   `json:"generate"`
	Voice    string `json:"voice,omitempty"`
}

type CreateDispatchResponse struct {
	Window            APIWindow `json:"window"`
	CoveredRepos      []string  `json:"covered_repos,omitempty"`
	Repos             []APIRepo `json:"repos,omitempty"`
	GeneratedText     string    `json:"generated_text,omitempty"`
	GeneratedMarkdown string    `json:"generated_markdown,omitempty"`
}

type APIWindow struct {
	NormalizedSince          string `json:"normalized_since"`
	NormalizedUntil          string `json:"normalized_until"`
	FirstCheckpointCreatedAt string `json:"first_checkpoint_created_at,omitempty"`
	LastCheckpointCreatedAt  string `json:"last_checkpoint_created_at,omitempty"`
}

type APIRepo struct {
	FullName string       `json:"full_name"`
	Sections []APISection `json:"sections"`
}

type APISection struct {
	Label   string      `json:"label"`
	Bullets []APIBullet `json:"bullets"`
}

type APIBullet struct {
	CheckpointID string   `json:"checkpoint_id"`
	Text         string   `json:"text"`
	Source       string   `json:"source"`
	Branch       string   `json:"branch"`
	CreatedAt    string   `json:"created_at"`
	Labels       []string `json:"labels"`
}

func (c *CloudClient) CreateDispatch(ctx context.Context, reqBody CreateDispatchRequest) (*CreateDispatchResponse, error) {
	var out CreateDispatchResponse
	if err := c.doJSON(ctx, http.MethodPost, "/api/v1/dispatch", reqBody, &out); err != nil {
		return nil, err
	}
	return &out, nil
}

func (c *CloudClient) doJSON(ctx context.Context, method, path string, reqBody, out any) error {
	var body io.Reader
	if reqBody != nil {
		data, err := json.Marshal(reqBody)
		if err != nil {
			return fmt.Errorf("marshal request body: %w", err)
		}
		body = bytes.NewReader(data)
	}

	req, err := http.NewRequestWithContext(ctx, method, c.baseURL+path, body)
	if err != nil {
		return fmt.Errorf("create request: %w", err)
	}
	req.Header.Set("Accept", "application/json")
	if reqBody != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.token != "" {
		req.Header.Set("Authorization", "Bearer "+c.token)
	}

	resp, err := c.http.Do(req)
	if err != nil {
		return fmt.Errorf("%s %s: %w", method, path, err)
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusUnauthorized {
		return errors.New("dispatch requires login — run `entire login`")
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		body, _ := io.ReadAll(io.LimitReader(resp.Body, 1<<20)) //nolint:errcheck // best-effort body read for error message
		trimmed := strings.TrimSpace(string(body))
		if trimmed == "" {
			return fmt.Errorf("%s %s: unexpected status %d", method, path, resp.StatusCode)
		}
		return fmt.Errorf("%s %s: unexpected status %d: %s", method, path, resp.StatusCode, trimmed)
	}
	if out == nil {
		return nil
	}
	if err := json.NewDecoder(resp.Body).Decode(out); err != nil {
		return fmt.Errorf("decode response: %w", err)
	}
	return nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"

	dispatchpkg "github.com/entireio/cli/cmd/entire/cli/dispatch"
	"github.com/spf13/cobra"
	"golang.org/x/term"
)

var runDispatch = dispatchpkg.Run
var renderDispatchMarkdown = dispatchpkg.RenderMarkdown
var dispatchTerminalMode = isTerminalWriter
var runInteractiveDispatch = defaultRunInteractiveDispatch
var renderTerminalMarkdown = defaultRenderTerminalMarkdown

func newDispatchCmd() *cobra.Command {
	var (
		flagLocal       bool
		flagSince       string
		flagUntil       string
		flagAllBranches bool
		flagRepos       []string
		flagOrg         string
		flagVoice       string
	)

	cmd := &cobra.Command{
		Use:    "dispatch",
		Short:  "Generate a dispatch summarizing recent agent work",
		Hidden: true,
		Long: `Generate a dispatch summarizing recent agent work.

Examples:
  entire dispatch
  entire dispatch --since 14d --all-branches
  entire dispatch --local
  entire dispatch --voice neutral`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			var (
				opts dispatchpkg.Options
				err  error
			)

			if shouldRunDispatchWizard(cmd.Flags().NFlag(), isTerminalStdin(os.Stdin), isTerminalWriter(cmd.OutOrStdout())) {
				opts, err = runDispatchWizard(cmd)
			} else {
				opts, err = parseDispatchFlags(cmd, flagLocal, flagSince, flagUntil, flagAllBranches, flagRepos, flagOrg, flagVoice)
			}
			if err != nil {
				if errors.Is(err, errDispatchCancelled) {
					return nil
				}
				return err
			}

			if err := runDispatchCommand(cmd.Context(), cmd.OutOrStdout(), opts); err != nil {
				if errors.Is(err, errDispatchCancelled) {
					return nil
				}
				return err
			}
			return nil
		},
	}

	cmd.Flags().BoolVar(&flagLocal, "local", false, "use local LLM tokens instead of server synthesis")
	cmd.Flags().StringVar(&flagSince, "since", "7d", "time window (Go duration, relative time, or ISO date)")
	cmd.Flags().StringVar(&flagUntil, "until", "", "window end time (defaults to now)")
	cmd.Flags().BoolVar(&flagAllBranches, "all-branches", false, "include all branches instead of the default branch scope")
	cmd.Flags().StringSliceVar(&flagRepos, "repos", nil, "server repo slugs (for example entireio/cli)")
	cmd.Flags().StringVar(&flagOrg, "org", "", "enumerate checkpoints across an org")
	cmd.Flags().StringVar(&flagVoice, "voice", "", "voice preset name, file path, or literal description")

	return cmd
}

func runDispatchCommand(ctx context.Context, outW io.Writer, opts dispatchpkg.Options) error {
	if dispatchTerminalMode(outW) {
		markdown, err := runInteractiveDispatch(ctx, outW, opts)
		if err != nil {
			return err
		}
		rendered, err := renderTerminalMarkdown(outW, markdown)
		if err != nil {
			return err
		}
		if _, err := fmt.Fprint(outW, rendered); err != nil {
			return fmt.Errorf("write dispatch output: %w", err)
		}
		return nil
	}

	result, err := runDispatch(ctx, opts)
	if err != nil {
		return err
	}
	if _, err := fmt.Fprint(outW, renderDispatchMarkdown(result)); err != nil {
		return fmt.Errorf("write dispatch output: %w", err)
	}
	return nil
}

func isTerminalStdin(file *os.File) bool {
	return term.IsTerminal(int(file.Fd())) //nolint:gosec // G115: uintptr->int is safe for fd
}

func shouldRunDispatchWizard(flagCount int, stdinIsTerminal bool, stdoutIsTerminal bool) bool {
	return flagCount == 0 && stdinIsTerminal && stdoutIsTerminal
}

func parseDispatchFlags(
	cmd *cobra.Command,
	flagLocal bool,
	flagSince string,
	flagUntil string,
	flagAllBranches bool,
	flagRepos []string,
	flagOrg string,
	flagVoice string,
) (dispatchpkg.Options, error) {
	return resolveDispatchOptions(
		flagLocal,
		flagSince,
		flagUntil,
		flagAllBranches,
		flagRepos,
		flagOrg,
		flagVoice,
		func() (string, error) {
			return GetCurrentBranch(cmd.Context())
		},
	)
}

func resolveDispatchOptions(
	flagLocal bool,
	flagSince string,
	flagUntil string,
	flagAllBranches bool,
	flagRepos []string,
	flagOrg string,
	flagVoice string,
	currentBranch func() (string, error),
) (dispatchpkg.Options, error) {
	if flagOrg != "" && len(flagRepos) > 0 {
		return dispatchpkg.Options{}, errors.New("--org and --repos are mutually exclusive")
	}
	if flagLocal && len(flagRepos) > 0 {
		return dispatchpkg.Options{}, errors.New("--repos cannot be used with --local")
	}
	if flagLocal && flagOrg != "" {
		return dispatchpkg.Options{}, errors.New("--org cannot be used with --local")
	}

	mode := dispatchpkg.ModeServer
	if flagLocal {
		mode = dispatchpkg.ModeLocal
	}

	var branches []string
	allBranches := flagAllBranches
	implicitCurrentBranch := false
	switch {
	case allBranches:
	case len(flagRepos) > 0, strings.TrimSpace(flagOrg) != "":
		branches = nil
	default:
		currentBranchName, branchErr := currentBranch()
		if branchErr != nil {
			return dispatchpkg.Options{}, branchErr
		}
		branches = []string{currentBranchName}
		implicitCurrentBranch = true
	}

	return dispatchpkg.Options{
		Mode:                  mode,
		RepoPaths:             append([]string(nil), flagRepos...),
		Org:                   flagOrg,
		Since:                 flagSince,
		Until:                 flagUntil,
		Branches:              branches,
		AllBranches:           allBranches,
		ImplicitCurrentBranch: implicitCurrentBranch,
		Voice:                 flagVoice,
	}, nil
}

package dispatch

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/go-git/go-git/v6"
)

func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
	token, err := lookupCurrentToken()
	if err != nil {
		return nil, fmt.Errorf("reading credentials: %w", err)
	}
	if token == "" {
		return nil, errors.New("dispatch requires login — run `entire login`")
	}

	now := nowUTC()
	sinceInput := strings.TrimSpace(opts.Since)
	if sinceInput == "" {
		sinceInput = "7d"
	}
	since, err := ParseSinceAtNow(sinceInput, now)
	if err != nil {
		return nil, err
	}
	until, err := ParseUntilAtNow(opts.Until, now)
	if err != nil {
		return nil, err
	}
	if !since.Before(until) {
		return nil, errors.New("--since must be before --until")
	}

	var repoScope any
	repoFullNames := append([]string(nil), opts.RepoPaths...)
	switch {
	case opts.Org == "" && len(repoFullNames) == 0:
		repoRoot, err := paths.WorktreeRoot(ctx)
		if err != nil {
			return nil, fmt.Errorf("not in a git repository: %w", err)
		}
		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
		if err != nil {
			return nil, fmt.Errorf("open repository: %w", err)
		}
		repoFullName, err := resolveRepoFullName(repo)
		if err != nil {
			return nil, err
		}
		repoScope = repoFullName
	case len(repoFullNames) == 1:
		repoScope = repoFullNames[0]
	case len(repoFullNames) > 1:
		repoScope = repoFullNames
	}

	branches := any(opts.Branches)
	if opts.AllBranches {
		branches = "all"
	}

	scopeLabel := scopeLabelForGeneration(opts)
	generateRemotely := scopeLabel == ""

	cloud := NewCloudClient(CloudConfig{BaseURL: api.BaseURL(), Token: token})
	reqBody := CreateDispatchRequest{
		Repo:     repoScope,
		Org:      opts.Org,
		Since:    since.Format(time.RFC3339),
		Until:    until.Format(time.RFC3339),
		Branches: branches,
		Generate: generateRemotely,
		Voice:    opts.Voice,
	}
	response, err := cloud.CreateDispatch(ctx, reqBody)
	if err != nil {
		return nil, err
	}

	dispatch := apiToDispatch(response)
	if generateRemotely {
		if strings.TrimSpace(dispatch.GeneratedText) == "" {
			return nil, errDispatchMissingMarkdown
		}
		return dispatch, nil
	}

	dispatch.GeneratedText, err = generateLocalDispatchWithScope(ctx, dispatch, opts.Voice, scopeLabel)
	if err != nil {
		return nil, err
	}
	if strings.TrimSpace(dispatch.GeneratedText) == "" {
		return nil, errDispatchMissingMarkdown
	}
	return dispatch, nil
}

func scopeLabelForGeneration(opts Options) string {
	if len(opts.RequestedOrganizations) > 1 {
		return fmt.Sprintf("%d organizations", len(opts.RequestedOrganizations))
	}
	return ""
}

func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
	if response == nil {
		return &Dispatch{}
	}

	repos := make([]RepoGroup, 0, len(response.Repos))
	for _, repo := range response.Repos {
		sections := make([]Section, 0, len(repo.Sections))
		for _, section := range repo.Sections {
			bullets := make([]Bullet, 0, len(section.Bullets))
			for _, bullet := range section.Bullets {
				bullets = append(bullets, Bullet{
					CheckpointID: bullet.CheckpointID,
					Text:         bullet.Text,
					Source:       bullet.Source,
					Branch:       bullet.Branch,
					CreatedAt:    parseAPITime(bullet.CreatedAt),
