	}

	return dispatchpkg.Options{
		Mode:                  mode,
		RepoPaths:             append([]string(nil), flagRepos...),
		Org:                   flagOrg,
		Since:                 flagSince,
		Until:                 flagUntil,
		Branches:              branches,
		AllBranches:           allBranches,
		ImplicitCurrentBranch: implicitCurrentBranch,
		Voice:                 flagVoice,
	}, nil
}

