export async function buildDispatchRecord(
  db: Db,
  userId: string,
  body: CreateDispatchRequest,
): Promise<DispatchDetail | null> {
  const scopeRepos = normalizeScopeValues(body.repo)
  const scopeOrgs = normalizeScopeValues(body.org)

  if (
    (scopeRepos.length === 0 && scopeOrgs.length === 0) ||
    (scopeRepos.length > 0 && scopeOrgs.length > 0)
  ) {
    return null
  }

  const window = normalizeWindow(body.since, body.until)
  const repoNames =
    scopeRepos.length > 0
      ? scopeRepos
      : [
          ...new Set(
            (await db.repos.getAccessibleByUser(userId))
              .filter((repo) => scopeOrgs.some((org) => repo.full_name.startsWith(`${org}/`)))
              .map((repo) => repo.full_name),
          ),
        ]
  if (repoNames.length === 0) {
    return null
  }

  const repos = await Promise.all(repoNames.map((repoName) => db.repos.getByFullName(repoName)))
  const repoData = (
    await Promise.all(
      repos.map((repo) => collectRepoDispatchData(db, userId, repo, body.branches, window)),
    )
  ).filter((repo): repo is RepoDispatchData => repo !== null)

  const coveredRepos = repoData.map((repo) => repo.fullName)
  if (coveredRepos.length === 0) {
    return null
  }

  const allBranches = [...new Set(repoData.flatMap((repo) => repo.selectedBranches))]
  const warnings = emptyWarnings()
  const filesTouched = new Set<string>()
  const checkpointTimestamps: string[] = []
  const usedCheckpointIDs = new Set<string>()

  for (const repo of repoData) {
    mergeWarnings(warnings, repo.warnings)
    for (const file of repo.filesTouched) {
      filesTouched.add(file)
    }
    for (const checkpointID of repo.usedCheckpointIDs) {
      usedCheckpointIDs.add(checkpointID)
    }
    for (const checkpoint of repo.checkpoints) {
      const timestamp = checkpoint.created_at ?? checkpoint.commit_date
      if (timestamp) checkpointTimestamps.push(timestamp)
    }
  }

  checkpointTimestamps.sort((left, right) => new Date(left).getTime() - new Date(right).getTime())
  window.first_checkpoint_created_at = checkpointTimestamps[0] ?? null
  window.last_checkpoint_created_at = checkpointTimestamps.at(-1) ?? null

  const repoGroups: DispatchRepoGroup[] = repoData.map((repo) => ({
    full_name: repo.fullName,
    sections: repo.sections,
  }))
  const title = summarizeTitle(scopeRepos, scopeOrgs, repoGroups.length)
  const totals: DispatchTotals = {
    checkpoints: repoData.reduce((sum, repo) => sum + repo.checkpoints.length, 0),
    used_checkpoint_count: usedCheckpointIDs.size,
    branches: allBranches.length,
    files_touched: filesTouched.size,
  }

  return {
    title,
    covered_repos: coveredRepos,
    branches: body.branches === "all" ? "all" : allBranches,
    voice: body.voice ? sanitizeVoice(body.voice) || null : null,
    window,
    totals,
    warnings,
    generated_markdown: "",
    repos: repoGroups,
  }
}

export function buildDispatchResponse(detail: DispatchDetail) {
  return {
    title: detail.title,
    covered_repos: detail.covered_repos,
    branches: detail.branches,
    voice: detail.voice,
    window: detail.window,
    totals: detail.totals,
    warnings: detail.warnings,
    generated_markdown: detail.generated_markdown,
    repos: detail.repos,
  }
}

export type DispatchContext = Context<{ Bindings: Env; Variables: Variables }>

// Per-user KV rate limit for dispatch creation. This is kept local to the
// dispatch flow because only dispatch generation needs a 1/min cap, and it is
// consumed after request validation so invalid retries do not burn the slot.
export async function consumeDispatchRateLimit(c: DispatchContext): Promise<Response | null> {
  const userId = c.get("userId")
  if (!userId) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const bucket = Math.floor(Date.now() / 1000 / DISPATCH_RATE_LIMIT_WINDOW_SECONDS)
  const bucketKey = `${DISPATCH_RATE_LIMIT_KEY_PREFIX}:${userId}:${bucket}`
  const current = await c.env.ENTIRE_CACHE.get<number>(bucketKey, "json")
  const count = current ?? 0

  if (count >= DISPATCH_RATE_LIMIT_MAX_REQUESTS) {
    return c.json({ error: "Rate limit exceeded" }, 429)
  }

  await c.env.ENTIRE_CACHE.put(bucketKey, JSON.stringify(count + 1), {
    expirationTtl: DISPATCH_RATE_LIMIT_WINDOW_SECONDS * 2,
  })

  return null
}

