  }

  if (!isAdmin(env, user.is_admin ?? false)) {
    return new Response(JSON.stringify({ error: "Not Found" }), {
      status: 404,
      headers: { "Content-Type": "application/json" },
    })
  }

  const posthog = getOrCreatePostHogClient(env)
  const flags = await getAllFeatureFlags(posthog, userId, {
    github_login: user.github_login,
    discovery_enabled: !!user.discovery_enabled,
    is_admin: !!(user.is_admin ?? false),
    is_entirehq_member: false,
  })
  if (!flags[FLAG_DISPATCHES]) {
    return new Response(JSON.stringify({ error: "Not Found" }), {
      status: 404,
      headers: { "Content-Type": "application/json" },
    })
  }

  return true
}

